import{c as a,Q as t,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const p="/assets/zh-cn_formulaimage_0000001943999269.prlZtmAk.png",i="/assets/zh-cn_formulaimage_0000001910040302.BiUxDgaz.png",l="/assets/zh-cn_formulaimage_0000001943999757.BbPoH5_R.png",A="data:image/png;base64,",o="data:image/png;base64,",r="data:image/png;base64,",c="data:image/png;base64,",g="data:image/png;base64,",m="/assets/%E7%AE%97%E5%AD%90%E8%AE%A1%E7%AE%97%E6%B5%81%E7%A8%8B.DD-OKHYy.png",f="/assets/zh-cn_formulaimage_0000002098517589.CZ-nAcog.png",E="/assets/zh-cn_formulaimage_0000002062439026.CelWodct.png",u="/assets/zh-cn_formulaimage_0000002098517777.C8bca3YN.png",d="/assets/zh-cn_formulaimage_0000002062439086.u7AIo5pQ.png",B="/assets/zh-cn_formulaimage_0000002098517781.BVH-7t1B.png",C="/assets/zh-cn_formulaimage_0000002062439090.uB2c0F1e.png",b="/assets/causal%E5%9C%BA%E6%99%AFatten_mask%E5%BD%A2%E7%8A%B6.yAGCUs8N.png",k="/assets/%E4%BC%98%E5%8C%96%E5%89%8D%E7%AE%97%E5%AD%90%E6%B5%81%E6%B0%B4.BwBgUnB2.png",h="/assets/causal%E5%9C%BA%E6%99%AFatten_mask%E5%BD%A2%E7%8A%B6-82.aUHKKcPu.png",S="/assets/%E5%9C%BA%E6%99%AF%E4%B8%80Profiling%E6%95%B0%E6%8D%AE.DoFj8wkk.png",w="/assets/%E5%9C%BA%E6%99%AF%E4%BA%8CProfiling%E6%95%B0%E6%8D%AE.DvC4RDZX.png",D="/assets/%E4%BC%98%E5%8C%96%E5%89%8D%E8%AE%A1%E7%AE%97%E5%9F%BA%E6%9C%AC%E5%9D%97%E5%8F%8A%E6%AC%A1%E6%95%B0.C-CMgmLQ.png",I="/assets/%E4%BC%98%E5%8C%96%E5%90%8E%E8%AE%A1%E7%AE%97%E5%9F%BA%E6%9C%AC%E5%9D%97%E5%8F%8A%E6%AC%A1%E6%95%B0.erkg2Gpr.png",P="/assets/%E5%AE%8C%E6%88%90mm1-mm2-mm3%E7%BC%93%E5%AD%98%E7%9A%84%E6%B5%81%E6%B0%B4.ClAQE_63.png",v="/assets/Vector%E7%AD%89Cube%E6%B5%81%E6%B0%B4%E7%9A%84%E9%97%B4%E9%9A%94%E6%8F%92%E5%85%A5Vector%E8%AE%A1%E7%AE%97.ATeY8BLH.png",N="/assets/causal%E5%9C%BA%E6%99%AF%E4%BC%98%E5%8C%96%E5%89%8D%E6%AF%8F%E4%B8%AA%E6%A0%B8%E8%AE%A1%E7%AE%97%E9%87%8F.BLgrcsMC.png",O="/assets/causal%E5%9C%BA%E6%99%AF%E4%BC%98%E5%8C%96%E5%90%8E%E6%AF%8F%E4%B8%AA%E6%A0%B8%E8%AE%A1%E7%AE%97%E9%87%8F.BGenoY9t.png",F="/assets/%E5%9C%BA%E6%99%AF%E4%B8%80Profiling%E6%95%B0%E6%8D%AE.DoFj8wkk.png",J="/assets/%E5%9C%BA%E6%99%AF%E4%B8%80%E4%BC%98%E5%8C%96%E5%90%8EProfiling%E6%95%B0%E6%8D%AE.CU32e-2C.png",R="/assets/%E5%9C%BA%E6%99%AF%E4%BA%8CProfiling%E6%95%B0%E6%8D%AE.DvC4RDZX.png",G="/assets/%E5%9C%BA%E6%99%AF%E4%BA%8C%E6%B5%81%E6%B0%B4%E5%9B%BE.CUMroy4R.png",Y=JSON.parse('{"title":"FlashAttention算子性能调优案例","description":"","frontmatter":{},"headers":[{"level":1,"title":"FlashAttention算子性能调优案例","slug":"flashattention算子性能调优案例"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/FlashAttention算子性能调优案例.md","filePath":"guide/算子实践参考/优秀实践/FlashAttention算子性能调优案例.md"}'),T={name:"guide/算子实践参考/优秀实践/FlashAttention算子性能调优案例.md"};function U(H,s,z,L,M,Q){return t(),e("div",null,[...s[0]||(s[0]=[n('<h1 id="flashattention算子性能调优案例" tabindex="-1">FlashAttention算子性能调优案例 <a class="header-anchor" href="#flashattention算子性能调优案例" aria-label="Permalink to &quot;FlashAttention算子性能调优案例&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例中的算子FlashAttentionScoreGrad，用于训练场景下计算注意力的反向输出，即FlashAttentionScore算子的反向计算。</p><p>已知注意力的正向计算公式为：</p><p><img src="'+p+'" alt=""></p><p>为方便表达，以变量S和P表示计算公式：</p><p><img src="'+i+'" alt=""></p><p><img src="'+l+'" alt=""></p><p><img src="'+A+'" alt=""></p><p>则注意力的反向计算公式为：</p><p><img src="'+o+'" alt=""></p><p><img src="'+r+'" alt=""></p><p><img src="'+c+'" alt=""></p><p><img src="'+g+'" alt=""></p><p>计算流程图如下：</p><p><strong>图 1</strong> 算子计算流程<br><img src="'+m+'" alt="" title="算子计算流程"></p><p>按照FlashAttention反向计算流程的实现，简介整体计算流程如下。对本算子的算法感兴趣的用户可简单了解，无需重点关注。</p><ol><li><p>重计算p，本步骤重计算了FlashAttention流程中的softmax结果p，计算结果保存在ub中。</p><p><img src="'+f+'" alt=""></p></li><li><p>计算dp，该计算包含matmul计算和dropout计算，matmul计算中，左矩阵为dy，右矩阵为转置后的value。</p><p><img src="'+E+'" alt=""></p></li><li><p>计算ds，本计算中，FlashSoftmaxGrad计算的入参为dy、正向输出attention_in，该结果与dp做减操作，最终的结果与p相乘得到结果ds。</p><p><img src="'+u+'" alt=""></p></li><li><p>计算dq，本计算将ds结果与key做matmul计算，并将结果与scale相乘得到结果dq。</p><p><img src="'+d+'" alt=""></p></li><li><p>计算dk，本计算将转置后的ds结果与query做matmul计算，并将结果与scale相乘得到结果dk。</p><p><img src="'+B+'" alt=""></p></li><li><p>计算dv，本计算将p的结果做drop计算，转置后与dy做matmul计算。</p><p><img src="'+C+'" alt=""></p></li></ol><p>本案例的验证平台为Atlas A2 训练系列产品/Atlas A2 推理系列产品，以两个场景为例，第一个场景的输入维度信息为：B=1，N1=12，N2=12，S1=6144，S2=6144，D=128，causal场景，即atten_mask的形状为下三角，如<a href="#fig9977418514">图2</a>。第二个场景的输入维度信息为：B=24，N1=5，N2=5，S1=9216，S2=9216，D=64，不带atten_mask和drop_mask输入。主要涉及的优化手段包括tiling基本块大小调整，核间负载均衡，CV流水并行，MTE2流水优化以及FixPipe流水优化等优化手段。</p><p><strong>图 2</strong> causal场景atten_mask形状<br><img src="'+b+`" alt="" title="causal场景atten_mask形状"></p><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>流水优化分析工具包括CAModel和Profiling工具，分别从两个方面分析：第一个是从Profiling工具生成的Profiling数据中分析各项流水的占比，第二个是从CAModel工具生成的打点图分析各流水并行情况。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><p>通过观察分析流水图和Profiling数据，结合优化经验来判断性能瓶颈点。在优化过程中不同阶段可能会出现不同的瓶颈点，需要不断优化以达到最佳性能。</p><ul><li><p>根据优化经验，循环间会存在一些不必要的性能开销，循环越多性能可能越差；满足UB最大空间限制的情况下，UB切分的基本块越大，循环越少。算子中通过InitBuffer接口分配UB buffer大小。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pipe-&gt;InitBuffer(ubBuffer, 120 * 1024);  </span></span>
<span class="line"><span>pipe-&gt;InitBuffer(tmpBuffer, 30 * 1024);  </span></span>
<span class="line"><span>pipe-&gt;InitBuffer(vecClc3, 8 * 1024);</span></span></code></pre></div><p>如上代码所示，InitBuffer接口的第二个参数表示buffer占用的大小，所有buffer大小的和即为占用的总空间。这里120 * 1024 + 30 * 1024 + 8 * 1024 = 158KB &lt; UB Size，没有充分利用UB空间。</p></li><li><p>观察如下流水图，绿色为Vector侧的流水，橙色为Cube侧的流水，可以看出两侧的流水都存在大段的空隙，CV之间流水很大程度上未并行，需要考虑CV流水优化。</p><p><strong>图 3</strong> 优化前算子流水<br><img src="`+k+'" alt="" title="优化前算子流水"></p></li><li><p>对于上述场景一，causal场景下可能存在核间分布不均匀的情况，如下图经过atten_mask掩码后，红色部分是算子需要计算的部分，绿色无需计算；如果不按照基本块的个数来分核，按照第一根轴的大小8（行）来分核，假设平均分到9个核上，每个核做ceil(8 / 9) = 1行，则第1个核只需做1个基本块，但是第8个核需要做8个基本块的计算，出现明显的负载不均衡。因此需要考虑将红色块均匀分到多个核上计算。</p><p><strong>图 4</strong> causal场景atten_mask形状<br><img src="'+h+'" alt="" title="causal场景atten_mask形状-82"></p></li><li><p>场景一的Profiling数据如下，aic_fixpipe_ratio占比极高，可能存在FixPipe bound。</p><p><strong>图 5</strong> 场景一Profiling数据<br><img src="'+S+'" alt="" title="场景一Profiling数据"></p></li><li><p>场景二的Profiling数据如下，mte2_ratio占比高，可能存在MTE2 bound。</p><p><strong>图 6</strong> 场景二Profiling数据<br><img src="'+w+'" alt="" title="场景二Profiling数据"></p></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><ul><li><p>优化点一：调整tiling基本块</p><p>在满足UB空间大小限制的前提下，tiling基本块的切分应尽可能大。如下图为优化前按照(64, 128)切分计算，总共需要循环计算32次。</p><p><strong>图 7</strong> 优化前计算基本块及次数<br><img src="'+D+'" alt="" title="优化前计算基本块及次数"></p><p>考虑到UB空间没有用满，基本块调整到(128, 128)，如下图优化后只需循环计算16次，切分后算子性能提升一倍。</p><p><strong>图 8</strong> 优化后计算基本块及次数<br><img src="'+I+`" alt="" title="优化后计算基本块及次数"></p></li><li><p>优化点二：CV流水并行</p><p>由于FAG算子中Cube计算比Vector计算快且存在依赖性，同时为了减少CV之间的通信次数，通过缓存机制使matmul提前计算多块，这里的缓存机制指的是将mm一次性计算多个基本块缓存到GM上。如下代码中，SetTail设置的singleCoreM和singleCoreN大小分别为BaseM，BaseN的倍数，即matmul一次发起多个基本块的计算，实现matmul结果的缓存，Vector侧分多次取matmul的结果。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm3.SetTail(s2CvExtend, -1, preS1Extend);  </span></span>
<span class="line"><span>mm3.SetTensorA(mulWorkSpaceGm[pingpongIdx * coreNum * cubeBaseMN + cBlockIdx * cubeBaseMN], true); </span></span>
<span class="line"><span>mm3.SetTensorB(queryGm[mm2aTensorOffsetCv]);  </span></span>
<span class="line"><span>mm3.template IterateAll&lt;false&gt;(dkWorkSpaceGm[bTensorOffsetCv], true);</span></span></code></pre></div><p><strong>图 9</strong> 完成mm1/mm2/mm3缓存的流水<br><img src="`+P+'" alt="" title="完成mm1-mm2-mm3缓存的流水"></p><p>如上图是实现mm1、mm2和mm3缓存的流水图，并行度提高，CV的间隔减小，提升了算子性能。</p><p><strong>图 10</strong> Vector等Cube流水的间隔插入Vector计算<br><img src="'+v+`" alt="" title="Vector等Cube流水的间隔插入Vector计算"></p><p>基于缓存mm1/mm2/mm3的优化后，在本轮Vector计算等Cube流水的间隔，插入下一轮循环的Vector计算，如上图所示，这样使Vector流水与Cube流水之间的并行度更高，反映到流水图中为Vector计算更密集。原计算过程伪代码与在CV间隔中插入下一轮Vector计算的伪代码，分别如以下两段所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 原计算过程伪代码 </span></span>
<span class="line"><span>// mm1计算;</span></span>
<span class="line"><span>dropout();</span></span>
<span class="line"><span>Sub();</span></span>
<span class="line"><span>// mm2计算;</span></span>
<span class="line"><span>Softmax();</span></span>
<span class="line"><span>AttenMask();</span></span>
<span class="line"><span>...</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 在Vector等Cube流水的间隔中，插入下一轮循环的Vector计算伪代码 </span></span>
<span class="line"><span>// mm1计算;</span></span>
<span class="line"><span>dropout();</span></span>
<span class="line"><span>Sub();</span></span>
<span class="line"><span>dropout(); // 下一轮循环的Vector计算</span></span>
<span class="line"><span>Sub();  // 下一轮循环的Vector计算</span></span>
<span class="line"><span>// mm2计算;</span></span>
<span class="line"><span>Softmax();</span></span>
<span class="line"><span>AttenMask();</span></span>
<span class="line"><span>...</span></span></code></pre></div></li><li><p>优化点三：每个核负载均衡</p><p><strong>图 11</strong> causal场景优化前每个核计算量<br><img src="`+N+'" alt="" title="causal场景优化前每个核计算量"></p><p><strong>图 12</strong> causal场景优化后每个核计算量<br><img src="'+O+'" alt="" title="causal场景优化后每个核计算量"></p><p>尽量实现每个核的计算量均匀，负载均衡。优化前的分核及每个核的计算量如<a href="#fig093211251714">图11 causal场景优化前每个核计算量</a>所示，按照第一根轴的大小8（行）来分核，平均分到9个核上，每个核计算ceil(8/9)=1行，第1个核只计算1个基本块，但是第8个核计算8个基本块。优化后如<a href="#fig7236118193316">图12 causal场景优化后每个核计算量</a>所示，红色块总共36个基本块，均分到每个核上，每个核的计算量为4个基本块，性能提升一倍。</p></li><li><p>优化点四： FIXPIPE优化</p><p>从采集的Profiling数据来看，Cube FixPipe占比高达81%，出现了很严重的bound（达到上限）。CAModel工具打印发现存在很多异常的128B搬运，排查代码，发现workspace地址未512B对齐。</p><p><strong>图 13</strong> 场景一优化前Profiling数据<br><img src="'+F+`" alt="" title="场景一优化前Profiling数据"></p><p>代码实现中使用SetGlobalBuffer接口设置workspace的起始地址，如果起始地址不是按照512B对齐，搬运效率会很低，可以强制<a href="./../SIMD算子性能优化/内存访问/GM地址尽量512B对齐.html">GM地址512Byte对齐</a>来避免这个情况。下面代码中ADDR_ALIGN_SIZE即为512。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// init workspace address  </span></span>
<span class="line"><span>syncGlobal.SetGlobalBuffer((__gm__ int32_t*)workspace);  </span></span>
<span class="line"><span>uint64_t workspaceOffsets = SYNC_GLOBAL_WORKSPACE_SIZE;  </span></span>
<span class="line"><span>dqWorkSpaceGm.SetGlobalBuffer((__gm__ float*)workspace + workspaceOffsets / sizeof(T2));  </span></span>
<span class="line"><span>workspaceOffsets = (workspaceOffsets + qPostBlockTotal * sizeof(float) + ADDR_ALIGN_SIZE) / ADDR_ALIGN_SIZE * ADDR_ALIGN_SIZE;  dkWorkSpaceGm.SetGlobalBuffer((__gm__ float*)workspace + workspaceOffsets / sizeof(T2));  </span></span>
<span class="line"><span>workspaceOffsets = (workspaceOffsets + kvPostBlockTotal * sizeof(float) + ADDR_ALIGN_SIZE) / ADDR_ALIGN_SIZE * ADDR_ALIGN_SIZE;  dvWorkSpaceGm.SetGlobalBuffer((__gm__ float*)workspace + workspaceOffsets / sizeof(T2));  </span></span>
<span class="line"><span>workspaceOffsets = (workspaceOffsets + kvPostBlockTotal * sizeof(float) + ADDR_ALIGN_SIZE) / ADDR_ALIGN_SIZE * ADDR_ALIGN_SIZE; </span></span>
<span class="line"><span>// matmul1 and matmul2 workspace size  </span></span>
<span class="line"><span>matmulWorkspaceSize = cubeBaseMN * sizeof(float); </span></span>
<span class="line"><span>mm1WorkspaceGm.SetGlobalBuffer((__gm__ T2*)(workspace + workspaceOffsets + cBlockIdx * matmulWorkspaceSize));  mm2WorkspaceGm.SetGlobalBuffer((__gm__ T2*)(workspace + workspaceOffsets + coreNum * matmulWorkspaceSize + cBlockIdx * matmulWorkspaceSize));   // drop workspace offset  </span></span>
<span class="line"><span>workspaceOffsets = (workspaceOffsets + coreNum * cubeBaseMN * sizeof(float) * INPUT_NUMS + ADDR_ALIGN_SIZE) / ADDR_ALIGN_SIZE * ADDR_ALIGN_SIZE;  </span></span>
<span class="line"><span>dropWorkSpaceGm.SetGlobalBuffer((__gm__ T1*)workspace + workspaceOffsets / sizeof(T1));   </span></span>
<span class="line"><span>// mul workspace offset  </span></span>
<span class="line"><span>workspaceOffsets = (workspaceOffsets + coreNum * cubeBaseMN * sizeof(half) * 2 + ADDR_ALIGN_SIZE) / ADDR_ALIGN_SIZE * ADDR_ALIGN_SIZE;  </span></span>
<span class="line"><span>mulWorkSpaceGm.SetGlobalBuffer((__gm__ T1*)workspace + workspaceOffsets / sizeof(T1));</span></span></code></pre></div><p>修改代码，workspace地址经过512B对齐后，FixPipe时间减半。</p><p><strong>图 14</strong> 场景一优化后Profiling数据<br><img src="`+J+'" alt="" title="场景一优化后Profiling数据"></p></li><li><p>优化点五：MTE2优化</p><p>结合如下的Profiling数据和流水图，可以看出MTE2 bound，且部分MTE2搬运时间异常。</p><p><strong>图 15</strong> 场景二Profiling数据<br><img src="'+R+'" alt="" title="场景二Profiling数据-83"></p><p><strong>图 16</strong> 场景二流水图<br><img src="'+G+'" alt="" title="场景二流水图"></p><p>将输入数据排布格式从BSH更改为BNSD后，数据搬运连续，不需要跳地址读取数据，搬运效率提升一倍，部分异常搬运时长降低了一半。</p></li></ul><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li>调整tiling基本块：理论评估Vector切块越大，计算和搬运循环次数越少，同时能够充分利用搬运带宽和Vector算力。基本块大小从(64, 128)增大到(128, 128)后，性能提升一倍，实测与理论分析一致。</li><li>CV流水并行：CV流水掩盖的时间即为提升的性能，符合预期的收益。</li><li>核间负载均衡：优化前负载最多的核计算量减少的倍数，即为预期提升的性能；案例中优化前负载最多的核的计算量大小为8块，优化后为4块，实际性能提升一倍，符合预期的收益。</li><li>FixPipe优化：从Profiling数据看出FixPipe占比0.8，优化后占比0.55，实测算子性能提升45%，与理论分析一致。</li><li>MTE2优化：从Profiling数据看出MTE2占比0.52，优化后占比减少一半，实测算子性能提升30%，与理论分析一致。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>融合算子场景，可参考此优化。</p>',31)])])}const V=a(T,[["render",U]]);export{Y as __pageData,V as default};
